def _generate_expression(self):
    # turn my _format attribute into the _expression attribute
    e = []
    for part in PARSE_RE.split(self._format):
        if not part:
            continue
        elif part == '{{':
            e.append(r'\{')
        elif part == '}}':
            e.append(r'\}')
        elif part[0] == '{':
            # this will be a braces-delimited field to handle
            # validate that braces are properly balanced within the part
            open_count = part.count('{') - 1  # subtract the first { which starts the field
            close_count = part.count('}')
            if open_count != close_count or open_count > 0:
                raise ValueError(
                    "unbalanced braces in format: %r" % self._format)
            e.append(self._handle_field(part))

